import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { roundCents } from './money.js';

/**
 * Generate an overdue report for invoices past their due date.
 * @param {Array} invoices - All invoices
 * @param {string} asOf - Cutoff date in YYYY-MM-DD format
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter((invoice) =>
      (invoice.status === 'issued' || invoice.status === 'partially_paid') &&
      invoice.dueDate < asOf
    )
    .map((invoice) => ({
      number: invoice.number,
      customerId: invoice.customerId,
      dueDate: invoice.dueDate,
      daysOverdue: daysBetween(invoice.dueDate, asOf),
      due: balanceDue(invoice),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * Generate a VAT summary across invoices.
 * @param {Array} invoices - All invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>} Sorted by rate descending
 */
export function vatSummary(invoices) {
  const vatMap = {};

  for (const invoice of invoices) {
    if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) {
      continue;
    }

    for (const line of invoice.lines) {
      const rate = line.vatRate;
      if (!vatMap[rate]) {
        vatMap[rate] = { rate, base: 0, vat: 0 };
      }

      const lineTotal = line.qty * line.unitPrice;
      const lineDiscount = roundCents(lineTotal * line.discountPercent / 100);
      const lineAmountAfterDiscount = lineTotal - lineDiscount;
      const lineVat = roundCents(lineAmountAfterDiscount * rate / 100);

      vatMap[rate].base += lineAmountAfterDiscount;
      vatMap[rate].vat += lineVat;
    }
  }

  return Object.values(vatMap).sort((a, b) => b.rate - a.rate);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { overdueInvoices, vatSummary } from '../src/reports.js';

test('overdueInvoices returns empty array for no invoices', () => {
  const result = overdueInvoices([], '2024-12-31');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  const result = overdueInvoices([inv.value], '2024-02-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued invoices past due date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.value.number);
  assert.equal(result[0].customerId, 'C-001');
  assert.ok(result[0].daysOverdue > 0);
});

test('overdueInvoices excludes invoices on due date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], issued.value.dueDate);
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes invoices before due date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], '2024-01-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes partially_paid invoices', () => {
  let inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: 0 }],
    terms: 'NET14',
  });
  let issued = issueInvoice(inv.value, []);

  const { total } = invoiceTotals(issued.value);
  const paymentResult = recordPayment(issued.value, { amount: Math.floor(total / 2), date: '2024-02-10' });
  const partiallyPaid = paymentResult.value;

  const result = overdueInvoices([partiallyPaid], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, Math.ceil(total / 2));
});

test('overdueInvoices excludes paid invoices', () => {
  let inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }],
    terms: 'NET14',
  });
  let issued = issueInvoice(inv.value, []);

  const { total } = invoiceTotals(issued.value);
  const paymentResult = recordPayment(issued.value, { amount: total, date: '2024-02-10' });
  const paid = paymentResult.value;

  const result = overdueInvoices([paid], '2024-03-01');
  assert.deepEqual(result, []);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-10',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(inv1.value, ['INV-2024-0001']);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-20',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2024-0002']);

  const result = overdueInvoices([issued2.value, issued1.value], '2024-02-10');
  assert.equal(result.length, 2);
  assert.ok(result[0].daysOverdue >= result[1].daysOverdue);
});


test('overdueInvoices calculates daysOverdue correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], '2024-01-31');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 16);
});

test('overdueInvoices includes correct fields', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }],
    terms: 'NET30',
  });
  const issued = issueInvoice(inv.value, []);

  const result = overdueInvoices([issued.value], '2024-03-01');
  assert.equal(result.length, 1);

  const item = result[0];
  assert.ok(item.number);
  assert.equal(item.customerId, 'C-002');
  assert.ok(item.dueDate);
  assert.ok(Number.isInteger(item.daysOverdue));
  assert.ok(item.due > 0);
});

test('overdueInvoices with multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }],
    terms: 'NET14',
  });
  const issued2 = issueInvoice(inv2.value, [issued1.value.number]);

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-01',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  const issued3 = issueInvoice(inv3.value, [issued1.value.number, issued2.value.number]);

  const result = overdueInvoices([issued1.value, issued2.value, issued3.value], '2024-03-01');
  assert.equal(result.length, 3);
  assert.ok(result[0].number);
  assert.ok(result[1].number);
  assert.ok(result[2].number);
});

test('overdueInvoices due equals balance for unpaid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);

  const { total } = invoiceTotals(issued.value);
  const result = overdueInvoices([issued.value], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, total);
});

test('overdueInvoices due equals balance for partially paid invoices', () => {
  let inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: 0 }],
    terms: 'NET14',
  });
  let issued = issueInvoice(inv.value, []);

  const { total } = invoiceTotals(issued.value);
  const payment = Math.floor(total / 3);
  const paymentResult = recordPayment(issued.value, { amount: payment, date: '2024-02-10' });
  const partiallyPaid = paymentResult.value;

  const result = overdueInvoices([partiallyPaid], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, total - payment);
});

test('vatSummary returns empty array for no invoices', () => {
  const result = vatSummary([]);
  assert.deepEqual(result, []);
});

test('vatSummary excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const result = vatSummary([inv.value]);
  assert.deepEqual(result, []);
});

test('vatSummary includes issued invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.ok(result[0].base > 0);
  assert.ok(result[0].vat > 0);
});

test('vatSummary includes partially_paid invoices', () => {
  let inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: 0 }],
  });
  let issued = issueInvoice(inv.value, []);

  const { total } = invoiceTotals(issued.value);
  const paymentResult = recordPayment(issued.value, { amount: Math.floor(total / 2), date: '2024-02-10' });
  const partiallyPaid = paymentResult.value;

  const result = vatSummary([partiallyPaid]);
  assert.equal(result.length, 1);
});

test('vatSummary includes paid invoices', () => {
  let inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }],
  });
  let issued = issueInvoice(inv.value, []);

  const { total } = invoiceTotals(issued.value);
  const paymentResult = recordPayment(issued.value, { amount: total, date: '2024-02-10' });
  const paid = paymentResult.value;

  const result = vatSummary([paid]);
  assert.equal(result.length, 1);
});

test('vatSummary groups by VAT rate', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 5, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 },
    ],
  });
  assert.equal(result1.ok, true);
  const issued = issueInvoice(result1.value, []);

  const result = vatSummary([issued.value]);
  const rates = result.map((item) => item.rate).sort((a, b) => b - a);
  assert.deepEqual(rates, [21, 9, 0]);
});

test('vatSummary sorts by rate descending', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 5, discountPercent: 0 },
      { sku: 'DES-HOUR', qty: 10, discountPercent: 0 },
    ],
  });
  assert.equal(result1.ok, true);
  const issued = issueInvoice(result1.value, []);

  const result = vatSummary([issued.value]);
  assert.ok(result[0].rate > result[1].rate);
  assert.ok(result[1].rate > result[2].rate);
});

test('vatSummary calculates base correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: 0 }],
  });
  const issued = issueInvoice(inv.value, []);
  const line = issued.value.lines[0];

  const result = vatSummary([issued.value]);
  const item = result[0];
  const lineTotal = line.qty * line.unitPrice;
  assert.equal(item.base, lineTotal);
});

test('vatSummary calculates base with discount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(inv.value, []);
  const line = issued.value.lines[0];

  const result = vatSummary([issued.value]);
  const item = result[0];
  const lineTotal = line.qty * line.unitPrice;
  const lineDiscount = Math.round(lineTotal * 10 / 100);
  const expectedBase = lineTotal - lineDiscount;
  assert.equal(item.base, expectedBase);
});

test('vatSummary calculates VAT correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: 0 }],
  });
  const issued = issueInvoice(inv.value, []);
  const line = issued.value.lines[0];

  const result = vatSummary([issued.value]);
  const item = result.find((r) => r.rate === 21);
  const lineTotal = line.qty * line.unitPrice;
  const expectedVat = Math.round(lineTotal * 21 / 100);
  assert.equal(item.vat, expectedVat);
});

test('vatSummary sums multiple lines with same VAT rate', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 50, discountPercent: 0 },
      { sku: 'DES-HOUR', qty: 50, discountPercent: 0 },
    ],
  });
  const issued = issueInvoice(inv.value, []);

  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);
  const line = issued.value.lines[0];
  const expectedBase = (line.qty * 2) * line.unitPrice;
  assert.equal(result[0].base, expectedBase);
});

test('vatSummary across multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-20',
    lines: [{ sku: 'DES-HOUR', qty: 20, discountPercent: 0 }],
  });
  const issued2 = issueInvoice(inv2.value, [issued1.value.number]);

  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 1);
  const line = issued1.value.lines[0];
  const expectedBase = (10 + 20) * line.unitPrice;
  assert.equal(result[0].base, expectedBase);
});

test('vatSummary with mixed statuses', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 0 }],
  });
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-20',
    lines: [{ sku: 'DES-HOUR', qty: 20, discountPercent: 0 }],
  });

  const result = vatSummary([issued1.value, inv2.value]);
  assert.equal(result.length, 1);
  const line = issued1.value.lines[0];
  const expectedBase = 10 * line.unitPrice;
  assert.equal(result[0].base, expectedBase);
});

test('vatSummary includes required fields', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 0 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = vatSummary([issued.value]);
  assert.equal(result.length, 1);

  const item = result[0];
  assert.ok('rate' in item);
  assert.ok('base' in item);
  assert.ok('vat' in item);
  assert.equal(Object.keys(item).length, 3);
});

test('vatSummary with all VAT rates', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
